INSERT INTO `announcements` (`id`, `title`, `priority`, `audience`, `content`, `author`, `created_at`) VALUES
(2, 'example', 'MEDIUM', 'Nurses Only', 'example', 'Ian Bagohara', '2026-09-18 16:08:29'),
(7, 'Appointment reschedule notice', 'MEDIUM', 'Patients Only', 'Your Curora appointment on 2026-09-29 at 13:00:00 needs attention because Doctor emergency leave. Please use this link to choose another available schedule: [RESCHEDULE_LINK]', 'Curora Schedule Disruption Engine', '2026-09-26 01:15:27'),
(8, 'Appointment cancellation notice', 'MEDIUM', 'Patients Only', 'Your check up appointment on 2026-10-13 at 13:00:00 was cancelled because Doctor emergency leave. Please choose a new appointment date here: [RESCHEDULE_LINK]', 'Curora Schedule Disruption Engine', '2026-09-26 01:28:10'),
(9, 'Appointment cancellation notice', 'MEDIUM', 'Patients Only', 'Your Follow up appointment appointment on 2026-09-28 at 08:00:00 was cancelled because Doctor emergency leave. Please choose a new appointment date here: [RESCHEDULE_LINK]', 'Curora Schedule Disruption Engine', '2026-09-26 02:25:00'),
(10, 'Appointment cancellation notice', 'MEDIUM', 'Patients Only', 'Your appointment on [DATE] at [TIME] was cancelled because Doctor has been called in for an urgent emergency surgical procedure. Please choose a new appointment date here: [RESCHEDULE_LINK]', 'Curora Schedule Disruption Engine', '2026-09-26 13:48:00'),
(1001, 'Emergency Leave — OB-GYN Consultations Cancelled (Oct 3)', 'HIGH', 'Patients Only', 'All OB-GYN consultations on Oct 3, 2026 are cancelled due to a doctor emergency leave. Affected patients have been sent a priority reschedule link to choose a new schedule. We apologize for the inconvenience.', 'Curora Administration', '2026-10-02 00:14:27'),
(1002, 'Facility Maintenance — Lobby & Lab (This Saturday)', 'MEDIUM', 'All Staff', 'The ground-floor lobby and laboratory will undergo scheduled maintenance this Saturday. Please route patients through the east wing entrance during this time.', 'Curora Administration', '2026-09-30 00:14:27'),
(1003, 'Holiday Schedule — Special Non-Working Days', 'MEDIUM', 'All', 'The clinic will follow the official holiday schedule for the upcoming special non-working days. Emergency on-call coverage will remain available for urgent cases.', 'Curora Administration', '2026-09-27 00:14:27'),
(1004, 'Mandatory Annual Staff Training', 'LOW', 'All Staff', 'All staff are required to attend the annual patient safety and data privacy training next month. Attendance will be tracked in the HR system.', 'Curora Administration', '2026-09-17 00:14:27'),
(1005, 'Archived: Pharmacy Holiday Hours (3 months ago)', 'LOW', 'All', 'Archived notice: the clinic pharmacy operated on reduced hours during the previous holiday season. This notice is retained for reference.', 'Curora Administration', '2026-07-04 00:14:27'),
(1006, 'Emergency: Intermittent Power Outage Notice', 'HIGH', 'All', 'Emergency notice from last month: the clinic experienced an intermittent power outage. Backup generators were deployed and all scheduled appointments were honored.', 'Curora Administration', '2026-09-12 00:14:27');
