INSERT INTO `consultations` (`ConsultationID`, `AppointmentID`, `PatientID`, `StaffID`, `VitalID`, `ConsultationDate`, `ConsultationTime`, `ChiefComplaint`, `Diagnosis`, `Treatment`, `LabRequest`, `Notes`, `FollowUpDate`, `Status`, `BloodPressure`, `Temperature`, `PulseRate`, `Weight`, `Height`, `CreatedAt`, `UpdatedAt`) VALUES
(1, 35, 1, 8, 4056, '2026-09-02', '13:20:29', 'Routine consultation', 'Primary: Acute Bacterial Sinusitis (ICD-10: J01.90)  Secondary: Allergic Rhinitis, seasonal (ICD-10: J30.1)', 'Complete a 7-day course of oral antibiotics.\r\n\r\nUse over-the-counter warm compresses over facial sinuses for 10–15 minutes twice daily.\r\n\r\nMaintain hypertonic saline nasal rinses twice daily to improve mucociliary clearance.\r\n\r\nFollow up in 10 days if symptoms fail to resolve, or sooner if red-flag symptoms develop (high fever, severe swelling around the eyes, severe headache).', NULL, 'History: Patient reports a 10-day history of nasal congestion, thick yellow nasal discharge, and facial pressure worsening over the last 3 days. Reports a mild frontal headache ($4/10$). Denies fever, shortness of breath, or changes in vision.\r\n\r\nExamination: Purulent discharge noted in bilateral nasal passages with mucosal edema. Mild tenderness to palpation over maxillary sinuses. Tympanic membranes clear bilaterally. Oropharynx clear without cobblestoning.', NULL, 'Completed', '120/80', 36.8, 78, NULL, NULL, '2026-09-02 12:54:13', '2026-10-04 00:52:21'),
(2, 36, 1, 8, 4057, '2026-09-02', '10:32:00', 'Hernia surgery follow-up', 'Post-operative healing progressing well', 'Continue aseptic wound dressing twice daily. Avoid heavy lifting for 2 weeks.', 'Complete blood count', 'Wound site clean with no signs of infection.', '2026-09-16', 'Completed', '118/78', 36.6, 74, NULL, NULL, '2026-09-02 12:54:13', '2026-10-04 00:52:21'),
(3, 34, 1, 8, 4058, '2026-09-02', '09:30:00', 'Cough and shortness of breath assessment', 'Primary: Acute Bronchitis (ICD-10: J20.9)  \r\nSecondary: Mild Asthma Exacerbation (ICD-10: J45.901)', 'Treatment Plan:\nInitiate short-acting inhaler therapy for acute dyspnea and wheezing.\r\n\r\nPrescribe a short course of oral corticosteroids to control airway inflammation.\r\n\r\nIncrease fluid intake, use a cool-mist humidifier, and rest.\r\n\r\nReturn for reassessment if shortness of breath worsens, chest pain develops, or fever occurs.\n\nPrescriptions:\n- Albuterol Sulfate — 90 mcg/actuation inhaler — 1–2 puffs every 4–6 hours as needed — 30 Days — Inhale deeply; wait 1 minute between puffs for acute shortness of breath.\n- Prednisone — 20 mg oral tablet — 2 tablets (40 mg) daily in the morning — 5 Days — Take with food to avoid stomach irritation. Do not stop abruptly.', NULL, 'History: Patient presents with a 5-day history of persistent productive cough with clear sputum and mild shortness of breath on exertion. Reports tightness in the chest and intermittent wheezing over the last 2 days. Denies high fever, night sweats, coughing up blood, or recent travel.\r\n\r\nExamination: Vital signs stable ($O_2$ saturation 97% on room air, RR 18 breaths/min). Oropharynx clear. Bilateral diffuse expiration wheezes and mild coarse crackles noted on lung auscultation. No accessory muscle use.', NULL, 'Completed', '120/80', 36.8, NULL, NULL, NULL, '2026-09-03 01:19:54', '2026-10-04 00:52:21'),
(4, 33, 1, 8, 4059, '2026-09-02', '09:00:00', 'Follow-up for post-op wound check', 'Primary: Postoperative Wound Check — Healing Surgical Incision (ICD-10: Z48.811)\r\n\r\nSecondary: Status Post Laparoscopic Appendectomy, Day 7 (ICD-10: Z98.890)', 'Treatment Plan:\r\nRemoved remaining surface Steri-Strips/sutures in office today.\r\n\r\nClear patient to resume normal daily activities; continue avoiding heavy lifting ($>10\\text{ lbs}$) for another 7–10 days.\r\n\r\nResume normal showering; pat incision sites dry gentle—do not scrub or submerge in baths/pools yet.\r\n\r\nReturn PRN if signs of infection occur (increasing redness, warmth, swelling, foul drainage, or fever $>38^{\\circ}\\text{C}$).\r\n\r\nPrescriptions:\r\n- Acetaminophen — 500 mg oral tablet — 1–2 tablets every 6 hours as needed — 5 Days — Use for mild residual incision discomfort. Do not exceed 3,000 mg/day.', NULL, 'History: Patient presents for a scheduled 1-week follow-up following an uncomplicated laparoscopic appendectomy. Reports well-controlled pain ($1/10$). Denies fever, chills, nausea, vomitting, or drainage from incision sites. Bowel habits have returned to baseline.\r\n\r\nExamination: Vital signs stable (Afebrile, BP 118/76, HR 72). Abdomen soft, non-tender, non-distended. Surgical portal sites in the lower abdomen are clean, dry, and intact. Well-approximated skin edges with minimal surrounding erythema. No signs of infection, hematoma, or seroma. Sutures/Steri-Strips intact.', NULL, 'Completed', '120/80', 36.8, NULL, NULL, NULL, '2026-09-03 01:52:00', '2026-10-04 00:52:21'),
(7, 59, 6, 8, 5512, '2026-09-12', '13:00:00', 'Stomachache', 'Primary: Acute Appendicitis (ICD-10: K35.80)\r\n\r\nStatus: Confirmed via Ultrasound', 'Procedure: Emergency Laparoscopic Appendectomy.\r\n\r\nPre-Operative Care: Maintain strict NPO (Nothing Per Os) status. Start continuous IV hydration with 0.9% Normal Saline at 100 mL/hr. Obtain emergency cardiac and anesthesia clearance.\r\n\r\nPost-Operative Care: Early ambulation after full recovery from anesthesia. Gradual diet advancement from clear liquids to regular soft diet as tolerated once bowel sounds return.', 'Complete Blood Count (CBC) with Differential', 'SUBJECTIVE:\nPatient reports sudden onset of periumbilical pain starting yesterday morning, which migrated to the right lower quadrant (RLQ) overnight. Rates pain at 8/10. Reports loss of appetite, one episode of vomiting, and low-grade fever. Denies urinary symptoms or history of similar pain.\n\nOBJECTIVE:\nPatient reports sudden onset of periumbilical pain starting yesterday morning, which migrated to the right lower quadrant (RLQ) overnight. Rates pain at 8/10. Reports loss of appetite, one episode of vomiting, and low-grade fever. Denies urinary symptoms or history of similar pain.\n\nASSESSMENT:\nAcute non-perforated appendicitis. Requires surgical intervention.\n\nPLAN:\nAdmit to general surgery ward for emergency laparoscopic appendectomy. Keep NPO (Nothing Per Os). Start IV fluids and prophylactic IV antibiotics.', '2026-09-22', 'Completed', '120/80', 36.8, NULL, 68.00, 1.70, '2026-09-12 15:19:30', '2026-10-04 00:52:21'),
(8, 61, 7, 8, NULL, '2026-09-12', '13:00:00', 'headache', '', '', '', '', NULL, 'Completed', '', NULL, NULL, NULL, NULL, '2026-09-12 16:00:13', '2026-09-12 16:00:49'),
